import{_ as d,o as a,c as e,a2 as o}from"./chunks/framework.CtrpDQpp.js";const r="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",i="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",l="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",s="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",n="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",h="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNsaGj4DwAFhAJ/2eTjmwAAAABJRU5ErkJggg==",q=JSON.parse('{"title":"第 7 章 区块编辑器全解析 🟢","description":"","frontmatter":{},"headers":[],"relativePath":"07-block-editor.md","filePath":"07-block-editor.md","lastUpdated":1792595797000}'),c={name:"07-block-editor.md"};function p(g,t,u,A,k,b){return a(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-7-章-区块编辑器全解析-🟢" tabindex="-1">第 7 章 区块编辑器全解析 🟢 <a class="header-anchor" href="#第-7-章-区块编辑器全解析-🟢" aria-label="Permalink to &quot;第 7 章 区块编辑器全解析 🟢&quot;">​</a></h1><blockquote><p>一句话导览：区块编辑器（Gutenberg）是 WordPress 7.1 的默认编辑器，本章从「区块是什么」讲起，带你吃透界面、核心区块、模式、可复用部件与排障方法，彻底告别复制粘贴式排版。</p></blockquote><p>上一章我们在文章编辑器里完成了发布全流程，本章回到「写作与排版」本身。区块编辑器自 WordPress 5.0 起成为默认编辑器，它不只是一个新的输入框，而是一套结构化的内容组织方式。学会用「区块」思考，你会发现复杂版面不再需要手写表格和 <code>&lt;div&gt;</code>。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>理解 Gutenberg 的由来与「区块即结构化内容」的思想，看懂文章保存后的 <code>wp:</code> 标记。</li><li>熟悉编辑器界面的每个区域：顶栏、插入器、画布、区块工具栏、设置面板、列表视图。</li><li>掌握五类核心区块的用途与区块的通用操作（移动、变换、分组、复制、锁定、复用）。</li><li>理解模式（Pattern）与可复用部件（同步模式）的区别，能独立完成两栏图文加 CTA 卡片布局。</li><li>记住常用键盘快捷键，知道何时需要经典编辑器插件，并能处理「无效区块」这类常见故障。</li></ul><h2 id="_7-1-gutenberg-的由来" tabindex="-1">7.1 Gutenberg 的由来 <a class="header-anchor" href="#_7-1-gutenberg-的由来" aria-label="Permalink to &quot;7.1 Gutenberg 的由来&quot;">​</a></h2><h3 id="原理说明" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>在 WordPress 5.0（2018 年底发布）之前，WordPress 使用的是 <strong>TinyMCE</strong> 经典编辑器——一个类似简化版 Word 的单一文本框，工具栏提供加粗、对齐、插入图片等按钮。它的问题很明显：</p><ul><li>内容是一整坨混合 HTML，复杂版面靠嵌套表格和内联样式拼凑。</li><li>想做一个「左图右文 + 按钮」的卡片，要么手写 HTML，要么依赖页面构建器插件。</li><li>内容样式与主题强耦合，换主题后排版经常散架。</li></ul><p><strong>Gutenberg（古腾堡）</strong> 项目以印刷术发明者命名，目标是把页面拆成一个个独立的「区块（Block）」：一段文字是段落区块，一张图片是图片区块，一列按钮是按钮区块。每个区块负责自己的结构、样式与设置，编辑器把它们组合成完整页面。</p><p>经过多个大版本的演进，7.1 时代的 Gutenberg 已经从「文章编辑器」扩展为**全站编辑（Full Site Editing）**的基础：小工具、导航菜单、页眉页脚、模板都由区块构成（主题侧的全站编辑在<a href="./13-customizer">第 13 章</a>与<a href="./23-template-hierarchy">第 23 章</a>展开）。</p><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：Gutenberg 是插件吗？</strong> 答：它有两种形态：核心代码已随 WordPress 自带；同时官方还在插件目录发布「Gutenberg」插件，那是抢先体验最新开发功能的测试通道，普通站点不需要安装。</li></ul><h2 id="_7-2-区块底层原理-内容是怎么保存的" tabindex="-1">7.2 区块底层原理：内容是怎么保存的 <a class="header-anchor" href="#_7-2-区块底层原理-内容是怎么保存的" aria-label="Permalink to &quot;7.2 区块底层原理：内容是怎么保存的&quot;">​</a></h2><h3 id="原理说明-1" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-1" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>在经典编辑器里，文章正文就是普通 HTML。而在区块编辑器里，正文是<strong>带 HTML 注释标记的 HTML</strong>。点击任意区块工具栏的「选项（三点）→ 编辑为 HTML」（Edit as HTML），或按 <code>Ctrl/Cmd + Shift + Alt + M</code> 切换到代码编辑器，你会看到类似内容：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- wp:heading {&quot;level&quot;:2} --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;为什么选择区块&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">h2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- /wp:heading --&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- wp:paragraph {&quot;align&quot;:&quot;center&quot;} --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;has-text-align-center&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;这是一段居中的文字，包含一个&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">strong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;加粗&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">strong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;词汇。&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- /wp:paragraph --&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- wp:image {&quot;id&quot;:128,&quot;sizeSlug&quot;:&quot;large&quot;,&quot;linkDestination&quot;:&quot;none&quot;} --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">figure</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wp-block-image size-large&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/wp-content/uploads/2026/10/team.jpg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;团队合影&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> class</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wp-image-128&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">figure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- /wp:image --&gt;</span></span></code></pre></div><p>规律非常清晰：</p><ul><li><code>&lt;!-- wp:区块名 --&gt;</code> 与 <code>&lt;!-- /wp:区块名 --&gt;</code> 是一对分隔注释，包裹该区块输出的 HTML。</li><li>注释中可以携带 JSON 配置（如 <code>{&quot;align&quot;:&quot;center&quot;}</code>），区块设置面板里的选项就保存在这里。</li><li>没有任何配置的简单区块就是 <code>&lt;!-- wp:paragraph --&gt;</code>。</li><li>还有一类自闭合的<strong>动态区块</strong>，如 <code>&lt;!-- wp:latest-posts {&quot;postsToShow&quot;:3} / --&gt;</code>，正文里不存渲染结果，而是在前台访问时由 PHP 实时查询输出——所以「最新文章」区块永远显示最新数据。</li></ul><h3 id="为什么这比短代码-shortcode-时代更可移植" tabindex="-1">为什么这比短代码（Shortcode）时代更可移植 <a class="header-anchor" href="#为什么这比短代码-shortcode-时代更可移植" aria-label="Permalink to &quot;为什么这比短代码（Shortcode）时代更可移植&quot;">​</a></h3><p>经典时代插件常让用户在正文里写短代码：<code>[gallery id=&quot;5&quot; columns=&quot;3&quot;]</code>、<code>[contact-form id=&quot;7&quot;]</code>。对比一下：</p><table tabindex="0"><thead><tr><th>对比维度</th><th>经典编辑器 + 短代码</th><th>区块编辑器 + 区块标记</th></tr></thead><tbody><tr><td>编辑体验</td><td>一行看不懂的方括号文本，靠弹窗填参数</td><td>可视化，所见即所得</td></tr><tr><td>内容结构</td><td>编辑器不知道 <code>[gallery]</code> 占多大、是什么</td><td>每个区块在画布中有真实结构</td></tr><tr><td>卸载插件后</td><td>正文中残留 <code>[xxx]</code> 纯文本</td><td>区块标记不匹配时提示「无效区块」，可保留内容或转 HTML</td></tr><tr><td>数据格式</td><td>插件私有语法，无法被其他工具解析</td><td>标准 HTML 注释 + JSON，任何工具都能识别处理</td></tr><tr><td>响应式与样式</td><td>依赖插件/主题输出，难以统一</td><td>区块自带结构化 class，主题可统一设计</td></tr></tbody></table><p>一句话：<strong>短代码是「给程序看的暗号」，区块标记是「人和程序都能读懂的结构化文档」。</strong></p><h3 id="常见问题-1" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-1" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：我可以直接改这些 <code>wp:</code> 注释吗？</strong> 答：学习时可以观察，日常排版不要手改。一旦注释与内部 HTML 不匹配，区块会报「无效」。改完想验证，可切回可视化编辑器。</li><li><strong>问：换主题后区块会丢吗？</strong> 答：区块标记随文章保存在数据库中，与主题无关，内容不会丢；但区块的某些样式（字体、配色）会随主题变化呈现不同外观，这是设计使然。</li></ul><h2 id="_7-3-认识编辑器界面" tabindex="-1">7.3 认识编辑器界面 <a class="header-anchor" href="#_7-3-认识编辑器界面" aria-label="Permalink to &quot;7.3 认识编辑器界面&quot;">​</a></h2><p>我们先从添加内容的入口——<strong>插入器</strong>看起，再总览全局。</p><h3 id="_7-3-1-插入器-inserter" tabindex="-1">7.3.1 插入器（Inserter） <a class="header-anchor" href="#_7-3-1-插入器-inserter" aria-label="Permalink to &quot;7.3.1 插入器（Inserter）&quot;">​</a></h3><p>点击编辑器顶部的「+」按钮（或区块工具栏上的「+」），打开的面板就是插入器。它分为「区块」「模式」「媒体」等标签页：</p><ul><li><strong>区块</strong>：按文本、媒体、设计、小工具、主题等分类列出所有可用区块，顶部搜索框支持拼音/英文/功能模糊搜索（搜「图」能找到图片、图库、封面）。</li><li><strong>模式</strong>：一组预设好的区块组合（整套 CTA、价格表、联系区），一键插入再改文字（详见 7.8 节）。</li><li><strong>媒体</strong>：直接浏览媒体库并插入图片、音频、视频。</li></ul><p><img src="`+r+'" alt="图 07-1：区块插入器"><em>图 07-1：区块插入器面板，左侧为分类标签与搜索框，右侧显示区块/模式预览网格</em></p><p>更快的插入方式是<strong>斜杠命令</strong>：在一个空段落里直接输入 <code>/</code>，立刻弹出可插入区块列表，继续输入 <code>图片</code>、<code>标题</code>、<code>表格</code> 等关键词，按回车即插入。熟练后 90% 的插入操作都不需要移动鼠标。</p><h3 id="_7-3-2-界面全景" tabindex="-1">7.3.2 界面全景 <a class="header-anchor" href="#_7-3-2-界面全景" aria-label="Permalink to &quot;7.3.2 界面全景&quot;">​</a></h3><p><img src="'+i+'" alt="图 07-2：区块编辑器界面全景标注"><em>图 07-2：区块编辑器全景，依次标注顶栏、列表视图、插入器、画布、区块工具栏、文档/区块设置面板</em></p><table tabindex="0"><thead><tr><th>区域</th><th>位置</th><th>作用</th></tr></thead><tbody><tr><td>顶部栏</td><td>窗口最上方</td><td>返回、列表视图、插入器、文档/区块设置切换齿轮、预览、发布/更新、选项（三点）</td></tr><tr><td>左侧面板</td><td>点「+」展开</td><td>插入器（区块/模式/媒体）</td></tr><tr><td>列表视图</td><td>顶栏按钮或 <code>Shift+Alt+O</code></td><td>以树形大纲显示全部区块，用于定位、拖拽、批量选择、锁定</td></tr><tr><td>画布</td><td>中央</td><td>写作与排版的主区域</td></tr><tr><td>区块工具栏</td><td>选中区块时浮现</td><td>变换、移动、对齐、加粗/斜体、链接、本区块的专属操作与选项菜单</td></tr><tr><td>设置面板</td><td>右侧（齿轮开关）</td><td>上半部分「文档」管整篇文章（状态、分类、特色图）；选中区块后切换为「区块」设置，管当前区块的所有参数</td></tr></tbody></table><p>右侧面板顶部有两个标签（面包屑式切换）：<strong>文章/页面设置</strong>与<strong>区块设置</strong>。很多新手找不到「图片怎么设链接」「按钮怎么改颜色」，都是因为停留在文档设置标签，选中区块后点击齿轮旁的「区块」标签即可。</p><p><img src="'+l+`" alt="图 07-3：区块设置面板"><em>图 07-3：选中图片区块后的右侧设置面板，包含替代文本、尺寸、链接目标等区块专属选项</em></p><h3 id="操作方法-你的第一个区块操作" tabindex="-1">操作方法：你的第一个区块操作 <a class="header-anchor" href="#操作方法-你的第一个区块操作" aria-label="Permalink to &quot;操作方法：你的第一个区块操作&quot;">​</a></h3><ol><li>新建文章，在空段落输入 <code>/标题</code>，回车插入「标题」区块，输入文字。</li><li>按回车自动新建段落，输入 <code>/图</code>，选择「图片」区块。</li><li>点击「上传」选择本地图片，上传后图片直接出现在画布中。</li><li>保持图片选中，在右侧区块设置的「替代文本」框填写无障碍描述。</li><li>点击右上角「预览」，在新标签查看前台效果。</li></ol><h3 id="常见问题-2" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-2" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：右侧设置面板不见了？</strong> 答：点击顶部右上角的齿轮图标切换显示；再确认选中了具体区块，否则显示的是文档设置。</li><li><strong>问：搜索不到某个区块？</strong> 答：该区块可能由插件提供而插件未启用，或被当前主题/管理员代码禁用；内置区块缺失时切换默认主题并停用插件排查。</li></ul><h2 id="_7-4-核心区块分组讲解" tabindex="-1">7.4 核心区块分组讲解 <a class="header-anchor" href="#_7-4-核心区块分组讲解" aria-label="Permalink to &quot;7.4 核心区块分组讲解&quot;">​</a></h2><p>内置区块按功能分为五大类，下面列出最常用的区块与典型用途。</p><h3 id="文本类" tabindex="-1">文本类 <a class="header-anchor" href="#文本类" aria-label="Permalink to &quot;文本类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区块</th><th>中文名称</th><th>用途与要点</th></tr></thead><tbody><tr><td><code>core/paragraph</code></td><td>段落</td><td>最基础的正文单元；回车即新建段落</td></tr><tr><td><code>core/heading</code></td><td>标题</td><td>H1-H6；文章主标题由模板提供，正文从 H2 开始用，勿跳级</td></tr><tr><td><code>core/list</code></td><td>列表</td><td>有序/无序，支持缩进多级；不要再用空格手动作列表</td></tr><tr><td><code>core/quote</code></td><td>引用</td><td>引文样式，含引用文字与署名</td></tr><tr><td><code>core/code</code></td><td>代码</td><td>行内代码片段样式，等宽字体显示，HTML 会被转义显示</td></tr><tr><td><code>core/preformatted</code></td><td>前置格式化</td><td>保留空格与换行的纯文本，适合 ASCII 示意</td></tr><tr><td><code>core/table</code></td><td>表格</td><td>简单表格，可设置表头、分段样式；复杂数据表仍建议电子表格截图或专业插件</td></tr><tr><td><code>core/verse</code></td><td>诗歌</td><td>保留换行排版的诗文</td></tr><tr><td><code>core/pullquote</code></td><td>拉引</td><td>版面中的大字强调引语</td></tr></tbody></table><h3 id="媒体类" tabindex="-1">媒体类 <a class="header-anchor" href="#媒体类" aria-label="Permalink to &quot;媒体类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区块</th><th>中文名称</th><th>用途与要点</th></tr></thead><tbody><tr><td><code>core/image</code></td><td>图片</td><td>单图，支持替代文本、尺寸、链接目标、圆角样式（媒体管理见<a href="./08-media-library">第 8 章</a>）</td></tr><tr><td><code>core/gallery</code></td><td>图库</td><td>多图网格排列，统一列数与裁剪</td></tr><tr><td><code>core/cover</code></td><td>封面</td><td>大图/视频背景上叠加文字，适合页头横幅</td></tr><tr><td><code>core/media-text</code></td><td>媒体和文本</td><td>左图右文（可左右互换）的两栏媒体块，移动端自动堆叠</td></tr><tr><td><code>core/audio</code></td><td>音频</td><td>原生播放器，适合播客片段</td></tr><tr><td><code>core/video</code></td><td>视频</td><td>播放本地视频文件；大视频建议改用 YouTube 等外链（见第 8 章）</td></tr><tr><td><code>core/file</code></td><td>文件</td><td>PDF/压缩包下载链接，带下载按钮</td></tr><tr><td><code>core/embed</code></td><td>嵌入</td><td>粘贴 URL 自动转换为 YouTube、Twitter 等嵌入内容</td></tr></tbody></table><h3 id="设计类" tabindex="-1">设计类 <a class="header-anchor" href="#设计类" aria-label="Permalink to &quot;设计类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区块</th><th>中文名称</th><th>用途与要点</th></tr></thead><tbody><tr><td><code>core/group</code></td><td>组</td><td>容器：把若干区块包成一组，统一背景色、内边距</td></tr><tr><td><code>core/columns</code></td><td>行列/栏目</td><td>多列布局的容器，内部每一列仍是一个容器（7.9 节实操）</td></tr><tr><td><code>core/row</code> / <code>core/stack</code></td><td>行 / 堆叠</td><td>子区块横向排列 / 纵向排列的弹性容器</td></tr><tr><td><code>core/buttons</code></td><td>按钮</td><td>按钮容器，内部放多个「按钮」子区块，可加圆角、边框、配色</td></tr><tr><td><code>core/separator</code></td><td>分隔符</td><td>水平分隔线，有几种线条样式</td></tr><tr><td><code>core/spacer</code></td><td>间隔</td><td>纯留白高度，可拖高度，用于调节版面呼吸感</td></tr></tbody></table><h3 id="主题类" tabindex="-1">主题类 <a class="header-anchor" href="#主题类" aria-label="Permalink to &quot;主题类&quot;">​</a></h3><p>这类区块从网站本身读取动态数据，常用于文章正文、小工具区和模板：</p><table tabindex="0"><thead><tr><th>区块</th><th>中文名称</th><th>用途</th></tr></thead><tbody><tr><td><code>core/latest-posts</code></td><td>最新文章</td><td>自动列出最新文章，可按分类过滤、显示日期/特色图</td></tr><tr><td><code>core/archives</code></td><td>归档</td><td>按月列出文章归档链接</td></tr><tr><td><code>core/latest-comments</code></td><td>最新评论</td><td>展示最新评论片段</td></tr><tr><td><code>core/tag-cloud</code></td><td>分类云</td><td>标签/分类字号云</td></tr><tr><td><code>core/shortcode</code></td><td>短代码</td><td>在区块世界里承载旧插件短代码的桥</td></tr><tr><td><code>core/html</code></td><td>自定义 HTML</td><td>直接写原生 HTML（统计代码、第三方嵌入脚本）</td></tr></tbody></table><h3 id="小工具类" tabindex="-1">小工具类 <a class="header-anchor" href="#小工具类" aria-label="Permalink to &quot;小工具类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区块</th><th>中文名称</th><th>用途</th></tr></thead><tbody><tr><td><code>core/search</code></td><td>搜索</td><td>站内搜索框</td></tr><tr><td><code>core/social-links</code></td><td>社交链接</td><td>微博、微信、GitHub 等社交图标链接组</td></tr></tbody></table><blockquote><p>插件还会注册大量第三方区块（表单、轮播、电商产品等），识别原则：<strong>核心内置区块优先，插件区块按需使用</strong>——因为文章中用得越多，将来对该插件的依赖越深（见 7.13 节）。</p></blockquote><h2 id="_7-5-区块通用操作" tabindex="-1">7.5 区块通用操作 <a class="header-anchor" href="#_7-5-区块通用操作" aria-label="Permalink to &quot;7.5 区块通用操作&quot;">​</a></h2><p>所有区块共享一套相同的操作语言，学会一个就会用全部。</p><table tabindex="0"><thead><tr><th>操作</th><th>怎么做</th><th>说明</th></tr></thead><tbody><tr><td>选中</td><td>单击区块</td><td>出现区块边框与工具栏</td></tr><tr><td>选中外层容器</td><td>按 <code>Esc</code> 或点击底部面包屑的父级名</td><td>在组/栏目中尤其常用</td></tr><tr><td>上移/下移</td><td>工具栏的 ↑/↓ 箭头</td><td>逐格移动</td></tr><tr><td>拖拽</td><td>按住区块左侧的<strong>拖柄</strong>（六点图标）拖动</td><td>出现蓝色指示线表示落点</td></tr><tr><td>变换（Transform）</td><td>工具栏左侧的区块图标</td><td>段落 ↔ 标题、列表 ↔ 引用、组 ↔ 行列等，保留文字</td></tr><tr><td>对齐</td><td>工具栏对齐按钮</td><td>左/中/右/宽幅/全宽（后两者需主题支持，见 FAQ）</td></tr><tr><td>复制</td><td>选项（三点）→ 复制，或 <code>Ctrl/Cmd + Shift + D</code> 复制出一个相同区块</td><td>「复制」是到剪贴板，可跨文章粘贴</td></tr><tr><td>重复</td><td>选项 → 重复</td><td>原地生成副本</td></tr><tr><td>在前方/后方插入</td><td>选项 → 插入前/插入后</td><td>精确控制插入位置</td></tr><tr><td>分组</td><td>选项 → 用组包裹（Group）</td><td>把当前区块包进组容器，便于加背景</td></tr><tr><td>移除</td><td>选项 → 移除，或选中后按删除键</td><td>内容随之删除，可 <code>Ctrl/Cmd+Z</code> 撤销</td></tr><tr><td>锁定</td><td>选项 → 锁定（Lock）</td><td>禁止移动/删除，模板中防止客户误改</td></tr><tr><td>复用</td><td>选项 → 创建可复用部件/模式</td><td>见 7.8 节</td></tr></tbody></table><h3 id="操作方法-用拖柄与面包屑操作嵌套区块" tabindex="-1">操作方法：用拖柄与面包屑操作嵌套区块 <a class="header-anchor" href="#操作方法-用拖柄与面包屑操作嵌套区块" aria-label="Permalink to &quot;操作方法：用拖柄与面包屑操作嵌套区块&quot;">​</a></h3><ol><li>插入一个「组」，组内放三个段落。</li><li>选中第二个段落，按 <code>Esc</code>，选中焦点上移到「组」——观察底部面包屑显示「文章 › 组 › 段落」。</li><li>抓住段落工具栏左侧的拖柄上下拖动，组内出现蓝色横线指示落点。</li><li>选中组，在区块设置中为整个组设置背景色，三个段落一起变色。</li></ol><h3 id="常见问题-3" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-3" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：拖拽时总是掉错位置？</strong> 答：嵌套布局中直接拖容易误判层级。复杂移动改用 7.7 节的列表视图，拖放位置更精确。</li><li><strong>问：「用组包裹」后后悔了？</strong> 答：选中组 → 工具栏选项 →「解组」（Ungroup），容器消失，内部区块保留。</li></ul><h2 id="_7-6-区块样式" tabindex="-1">7.6 区块样式 <a class="header-anchor" href="#_7-6-区块样式" aria-label="Permalink to &quot;7.6 区块样式&quot;">​</a></h2><h3 id="原理说明-2" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-2" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>同一个区块可以有多种预设外观，称为<strong>区块样式（Block Styles）</strong>。例如图片区块有「默认」「圆形」（圆角裁切成圆）；按钮有「填充」「轮廓」；表格有「默认」「条纹」。它在区块工具栏或右侧设置面板的「样式」区域以缩略图/按钮形式出现。</p><p>区块样式由核心、主题或插件注册，本质是给区块 HTML 追加一个修饰 class（如 <code>is-style-rounded</code>），切换样式不改变内容，只换外观。</p><h3 id="操作方法" tabindex="-1">操作方法 <a class="header-anchor" href="#操作方法" aria-label="Permalink to &quot;操作方法&quot;">​</a></h3><ol><li>插入一个按钮区块并输入文字。</li><li>在右侧区块设置的「样式」中，在「填充」与「轮廓」之间切换，观察画布。</li><li>插入图片区块，在「样式」中选「圆形」，图片立即变为圆形裁切。</li><li>在「颜色」「排版」「尺寸」等折叠面板中还可以做更细的局部覆盖。</li></ol><h3 id="常见问题-4" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-4" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：别人截图里的样式我这里没有？</strong> 答：部分样式由主题注册（如特定按钮形状）。换用支持该样式的主题，或由开发者通过代码注册默认样式（第 22 章后的主题开发内容）。</li></ul><h2 id="_7-7-列表视图-复杂版面的导航仪" tabindex="-1">7.7 列表视图：复杂版面的导航仪 <a class="header-anchor" href="#_7-7-列表视图-复杂版面的导航仪" aria-label="Permalink to &quot;7.7 列表视图：复杂版面的导航仪&quot;">​</a></h2><h3 id="原理说明-3" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-3" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>当文章有几十个区块、出现三四层嵌套时，在画布中精准选中某个区块会变得困难。<strong>列表视图（List View）</strong> 把整篇文章展开成一棵可折叠的树：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文章</span></span>
<span class="line"><span>├─ 封面</span></span>
<span class="line"><span>├─ 组（特性区）</span></span>
<span class="line"><span>│  ├─ 标题（H2）</span></span>
<span class="line"><span>│  ├─ 栏目</span></span>
<span class="line"><span>│  │  ├─ 列</span></span>
<span class="line"><span>│  │  │  └─ 段落 ×3</span></span>
<span class="line"><span>│  │  └─ 列</span></span>
<span class="line"><span>│  └─ 按钮</span></span>
<span class="line"><span>└─ 分隔符</span></span></code></pre></div><p>在列表视图中可以：单击直接定位并选中深层区块；按住拖柄上下拖动调整顺序与层级；按住 <code>Shift</code> 多选后整体移动；已锁定区块显示锁形图标。</p><p><img src="`+s+'" alt="图 07-4：列表视图"><em>图 07-4：列表视图中的嵌套区块树，拖柄、锁形标记与选中高亮清晰可见</em></p><h3 id="操作方法-1" tabindex="-1">操作方法 <a class="header-anchor" href="#操作方法-1" aria-label="Permalink to &quot;操作方法&quot;">​</a></h3><ol><li>按 <code>Shift+Alt+O</code>（macOS 为 <code>Shift+Option+O</code>）打开列表视图。</li><li>点击树中某个区块，画布自动滚动并选中它。</li><li>按住 <code>Shift</code> 连选两个区块，拖动整组到封面之前。</li><li>右键区块名 →「锁定」，在弹窗中勾选「禁止移动」「禁止删除」，回画布验证工具栏变灰。</li></ol><h2 id="_7-8-模式与可复用部件" tabindex="-1">7.8 模式与可复用部件 <a class="header-anchor" href="#_7-8-模式与可复用部件" aria-label="Permalink to &quot;7.8 模式与可复用部件&quot;">​</a></h2><h3 id="原理说明-4" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-4" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p><strong>模式（Pattern）</strong> 是官方设计好的区块组合模板：一整套「关于我」简介卡、三栏价格表、FAQ 折叠区、带背景图的行动号召区。插入后内容完全属于你，随意修改，互不影响——这叫<strong>非同步模式（Non-synced Pattern）</strong>。</p><p><strong>可复用部件</strong>（旧称「可复用区块」，WordPress 6.3 后归入<strong>同步模式 Synced Pattern</strong>）是另一种用法：把一个区块（或一组区块）保存为命名部件，之后可以插入到任意文章/页面。它的关键特性是：<strong>所有插入位置共享同一个数据源，改一处，全站所有位置同步更新</strong>。</p><table tabindex="0"><thead><tr><th>对比</th><th>模式（普通 Pattern）</th><th>可复用部件（同步模式）</th></tr></thead><tbody><tr><td>插入后修改</td><td>只影响本篇这一处</td><td>默认进入「部件编辑」，改动全站同步</td></tr><tr><td>典型用途</td><td>快速搭一个价格表骨架</td><td>全站统一的 CTA 卡片、订阅提示、联系方式块</td></tr><tr><td>能否解耦</td><td>本来就独立</td><td>可在某一处「脱离/转为普通区块」成为独立副本</td></tr><tr><td>管理位置</td><td>插入器「模式」标签 / 主题目录</td><td>站点编辑器 → 模式 → 我的模式（同步模式管理库）</td></tr></tbody></table><p><img src="'+n+'" alt="图 07-5：可复用部件管理界面"><em>图 07-5：站点编辑器中的模式管理界面，「我的模式」下列出全部可复用部件，可重命名、编辑与导出</em></p><h3 id="操作方法-创建并使用一个可复用-cta-部件" tabindex="-1">操作方法：创建并使用一个可复用 CTA 部件 <a class="header-anchor" href="#操作方法-创建并使用一个可复用-cta-部件" aria-label="Permalink to &quot;操作方法：创建并使用一个可复用 CTA 部件&quot;">​</a></h3><ol><li>在文章中插入一个「组」：内部放一个标题（「还没决定？先免费试用 14 天」）、一个段落、一个按钮（文字「立即开始」）。</li><li>为组设置背景色与内边距，排版满意后选中整个组。</li><li>点击组工具栏「选项（三点）→ 创建可复用部件/模式」，命名为「全站 CTA-免费试用」，确认保存。</li><li>新开一篇文章，用插入器的「模式 → 我的模式」或搜索部件名，把它插入正文。</li><li>回到第一篇文章，点击该部件上的「编辑部件/模式」，把按钮文案改为「免费注册」，更新。</li><li>刷新第二篇文章查看——按钮文案已同步改变，这就是「改一处、全站变」。</li></ol><blockquote><p>模式还可以从官方模式目录浏览导入；区块主题会自带大量主题级模式。主题侧的模式注册将在第 23 章学习。</p></blockquote><h3 id="常见问题-5" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-5" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：只想在这篇文章里改这个部件，怎么办？</strong> 答：在该实例工具栏选项中选择「脱离/分离为常规区块」（Detach），它就变成普通区块副本，与同步部件再无关联。</li><li><strong>问：删除可复用部件会影响已插入的文章吗？</strong> 答：删除部件后，已有实例会提示失效，可按提示转为普通区块保留内容；删除前建议先检查引用位置。</li></ul><h2 id="_7-9-实操-两栏图文-cta-卡片" tabindex="-1">7.9 实操：两栏图文 + CTA 卡片 <a class="header-anchor" href="#_7-9-实操-两栏图文-cta-卡片" aria-label="Permalink to &quot;7.9 实操：两栏图文 + CTA 卡片&quot;">​</a></h2><p>下面用点击级步骤做一个完整版面：上方两栏图文，下方一个整宽 CTA 卡片。</p><ol><li>新建空白文章，先输入 <code>/行列</code>，插入「栏目/行列」（Columns）区块，在弹出的预设中选择两个等宽列。</li><li>点击左列中的「+」，插入「标题」（H3）输入「自动备份，安心睡觉」，再插一个段落写两三句介绍。</li><li>点击右列中的「+」，插入「图片」区块，从媒体库选图（无图时先上传，方法见<a href="./08-media-library">第 8 章</a>）。</li><li>选中最外层「栏目」区块，在右侧设置中把「垂直对齐」设为「居中」；在「列间距」中调宽两列间距。</li><li>在栏目区块<strong>下方</strong>新建区块：输入 <code>/组</code> 插入「组」，在组内依次放一个 H2 标题、一个段落、一个「按钮」区块。</li><li>选中「组」，在区块设置中设置背景色、文字颜色、内边距；选中「按钮」，设置链接与轮廓样式。</li><li>如果想让 CTA 在窄屏上更舒展，可把组的对齐设为「宽幅」（需主题支持 <code>align-wide</code>，见 FAQ）。</li><li>点击「预览」检查移动端：浏览器开发者工具切到手机视图，确认两栏自动堆叠、按钮可点。</li><li>满意后按 7.8 节把组保存为可复用部件，供其他文章复用。</li></ol><h2 id="_7-10-编辑器偏好设置" tabindex="-1">7.10 编辑器偏好设置 <a class="header-anchor" href="#_7-10-编辑器偏好设置" aria-label="Permalink to &quot;7.10 编辑器偏好设置&quot;">​</a></h2><p>顶部「选项（三点）→ 偏好设置」（Preferences）中常用开关：</p><table tabindex="0"><thead><tr><th>偏好</th><th>作用</th></tr></thead><tbody><tr><td>顶部工具栏（Top toolbar）</td><td>区块工具栏固定到屏幕顶部，避免遮挡内容</td></tr><tr><td>聚光灯模式（Spotlight）</td><td>非当前区块变淡，减少干扰</td></tr><tr><td>全屏模式（Fullscreen）</td><td>隐藏后台左侧菜单，纯写作</td></tr><tr><td>显示按钮文本（Show button text labels）</td><td>工具栏图标旁显示中文文字，新手友好</td></tr><tr><td>文档概览（Overview）</td><td>显示字数、字数统计与标题大纲</td></tr><tr><td>面板</td><td>控制摘要、引用通告、讨论等面板是否显示</td></tr><tr><td>代码编辑器</td><td>以代码方式编辑整篇文章（谨慎使用）</td></tr><tr><td>外观</td><td>编辑器界面明暗主题跟随系统或手动指定</td></tr></tbody></table><p>这些是<strong>用户级偏好</strong>：只影响当前登录用户的账号，不影响其他作者，可放心尝试。</p><h2 id="_7-11-键盘快捷键速查" tabindex="-1">7.11 键盘快捷键速查 <a class="header-anchor" href="#_7-11-键盘快捷键速查" aria-label="Permalink to &quot;7.11 键盘快捷键速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>Windows / Linux</th><th>macOS</th></tr></thead><tbody><tr><td>插入区块（斜杠命令）</td><td>空段落输入 <code>/</code></td><td>空段落输入 <code>/</code></td></tr><tr><td>复制选中区块</td><td><code>Ctrl + Shift + D</code></td><td><code>Cmd + Shift + D</code></td></tr><tr><td>撤销 / 重做</td><td><code>Ctrl + Z</code> / <code>Ctrl + Shift + Z</code></td><td><code>Cmd + Z</code> / <code>Cmd + Shift + Z</code></td></tr><tr><td>插入/编辑链接</td><td><code>Ctrl + K</code></td><td><code>Cmd + K</code></td></tr><tr><td>加粗 / 斜体</td><td><code>Ctrl + B</code> / <code>Ctrl + I</code></td><td><code>Cmd + B</code> / <code>Cmd + I</code></td></tr><tr><td>打开/关闭列表视图</td><td><code>Shift + Alt + O</code></td><td><code>Shift + Option + O</code></td></tr><tr><td>打开/关闭设置面板</td><td><code>Ctrl + Shift + ,</code></td><td><code>Cmd + Shift + ,</code></td></tr><tr><td>可视化/代码编辑器切换</td><td><code>Ctrl + Shift + Alt + M</code></td><td><code>Cmd + Shift + Option + M</code></td></tr><tr><td>选中父级区块</td><td><code>Esc</code></td><td><code>Esc</code></td></tr><tr><td>保存草稿</td><td><code>Ctrl + S</code></td><td><code>Cmd + S</code></td></tr><tr><td>快捷键帮助面板</td><td><code>Shift + Alt + H</code></td><td><code>Shift + Option + H</code></td></tr></tbody></table><blockquote><p>快捷键可能随版本微调，最权威的清单在编辑器内：选项（三点）→「快捷键」。</p></blockquote><h2 id="_7-12-与经典编辑器共存" tabindex="-1">7.12 与经典编辑器共存 <a class="header-anchor" href="#_7-12-与经典编辑器共存" aria-label="Permalink to &quot;7.12 与经典编辑器共存&quot;">​</a></h2><h3 id="原理说明-5" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-5" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>官方插件目录提供 <strong>Classic Editor（经典编辑器）</strong> 插件，启用后可恢复 TinyMCE 界面，并且与区块编辑器共存：</p><ul><li>全站默认编辑器可在「设置 → 撰写」中选择经典或区块。</li><li>文章列表会出现「使用经典编辑器编辑」「使用区块编辑器编辑」两种入口。</li><li>区块编辑器中保留了一个 <strong>「经典」区块（Classic Block）</strong>：它在画布中嵌入一个 TinyMCE 小编辑器，适合维护那些大量依赖旧编辑器按钮/短代码的老文章。</li></ul><p><img src="'+h+'" alt="图 07-6：区块编辑器与经典编辑器对比"><em>图 07-6：左侧为经典编辑器单一文本框，右侧为区块编辑器的结构化画布与区块工具栏</em></p><p>什么时候该装经典编辑器？</p><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>新站、新内容</td><td>不装，直接学区块编辑器</td></tr><tr><td>老站几百篇旧文、作者群体拒绝改变</td><td>可装，逐步过渡，作者可逐篇尝试</td></tr><tr><td>某些老旧插件只能在经典编辑器里通过按钮插短代码</td><td>可装，或用「经典」区块/短代码区块局部兼容</td></tr><tr><td>页面构建器（Elementor 等）重度站点</td><td>与构建器插件并行使用，文章仍建议用区块</td></tr></tbody></table><p>经典编辑器是官方维护的兼容工具，不是「更专业」的选择。新内容坚持用区块，长期可移植性最好。</p><h3 id="常见问题-6" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题-6" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><ul><li><strong>问：装了经典编辑器后还能用区块吗？</strong> 答：可以。两种编辑器并行，旧文用经典打开、新文用区块写；同篇文章也可以反复切换（区块内容在经典编辑器中会显示为区块标记/区块占位，尽量固定一种编辑器维护同一篇文章）。</li></ul><h2 id="_7-13-无效区块与恢复失败" tabindex="-1">7.13 无效区块与恢复失败 <a class="header-anchor" href="#_7-13-无效区块与恢复失败" aria-label="Permalink to &quot;7.13 无效区块与恢复失败&quot;">​</a></h2><h3 id="原理说明-6" tabindex="-1">原理说明 <a class="header-anchor" href="#原理说明-6" aria-label="Permalink to &quot;原理说明&quot;">​</a></h3><p>打开旧文章时偶尔会看到红色提示：「此区块已损坏或无效」「此区块已被删除或停用」。常见原因：</p><ol><li>提供该区块的<strong>插件被停用或卸载</strong>，编辑器不认识标记了。</li><li>插件/主题升级后<strong>区块输出结构发生变化</strong>，与已保存的 HTML 对不上。</li><li>手动粘贴/代码编辑改坏了 <code>wp:</code> 注释。</li><li>文章是经典编辑器写的、被外部工具修改过 HTML。</li></ol><p>处理手段按代价从低到高：</p><ul><li>点击「<strong>尝试区块恢复</strong>」（Attempt Block Recovery），大多数结构轻微不匹配可自动修复。</li><li>工具栏选项 →「作为 HTML 编辑」，核对并修正标记后切回可视化。</li><li>从<a href="./06-posts-and-pages#636-修订版本历史快照与对比恢复">修订版本</a>恢复到正常版本（第 6 章 6.3.6）。</li><li>若区块来自已卸载插件且确认不再需要：保留内部文字（转成普通区块/自定义 HTML）后删除占位。</li><li>若是动态区块（如某插件的轮播），重新启用对应插件即可恢复，正文数据没有丢。</li></ul><h3 id="操作方法-故意制造一次失效并修复" tabindex="-1">操作方法：故意制造一次失效并修复 <a class="header-anchor" href="#操作方法-故意制造一次失效并修复" aria-label="Permalink to &quot;操作方法：故意制造一次失效并修复&quot;">​</a></h3><ol><li>启用一个提供前台区块的插件，插入其区块并更新文章。</li><li>停用该插件，刷新编辑界面，观察「区块无效」提示。</li><li>点击「尝试区块恢复」或先以 HTML 查看残留标记；重新启用插件，区块恢复。</li><li>这就是「插件卸载后内容残留」的真实过程，选型插件时要想到这一步。</li></ol><h2 id="_7-14-移动端与-wordpress-app" tabindex="-1">7.14 移动端与 WordPress App <a class="header-anchor" href="#_7-14-移动端与-wordpress-app" aria-label="Permalink to &quot;7.14 移动端与 WordPress App&quot;">​</a></h2><p>WordPress 官方 iOS/Android App 内置了移动版区块编辑器，支持段落、标题、图片等常用区块，适合临时发文、改错别字、审核评论；复杂嵌套布局与精细样式仍建议在桌面端完成。App 连接站点走 REST API（Jetpack 或应用密码授权），应用密码在「用户 → 个人资料」底部管理。平板上配合蓝牙键盘，斜杠命令与多数快捷键同样可用。</p><h2 id="_7-15-常见问题速查" tabindex="-1">7.15 常见问题速查 <a class="header-anchor" href="#_7-15-常见问题速查" aria-label="Permalink to &quot;7.15 常见问题速查&quot;">​</a></h2><ul><li><strong>问：从 Word/网页粘贴后变成一堆奇怪区块、格式全乱？</strong> 答：先撤销（<code>Ctrl/Cmd+Z</code>），改用纯文本粘贴：Windows <code>Ctrl + Shift + V</code>、macOS <code>Cmd + Shift + V</code>，再用标题、列表区块重新排版。</li><li><strong>问：编辑器白屏或卡在加载动画？</strong> 答：按「禁用插件排查法」处理：停用全部插件后逐个启用，定位冲突插件；同时按 <code>F12</code> 打开浏览器控制台（Console）查看红色报错；管理后台加载的优化类脚本（自定义管理 JS、广告拦截插件）也可能拦截编辑器请求。排查思路同<a href="./38-troubleshooting">第 38 章</a>。</li><li><strong>问：自定义 CSS 类名在哪里填？</strong> 答：选中区块 → 右侧区块设置 → 顶部「高级（Advanced）」折叠区 →「附加 CSS 类」（Additional CSS class(es)）。多个类名用空格分隔。</li><li><strong>问：对齐里的「宽幅/全宽」按钮点了没效果？</strong> 答：当前主题没有声明宽幅支持。经典主题需在 <code>functions.php</code> 中加入 <code>add_theme_support( &#39;align-wide&#39; );</code>，区块主题需在 <code>theme.json</code> 中配置对应布局宽度（第 23 章详解）。</li><li><strong>问：为什么改一个可复用部件，全站的都变了？</strong> 答：这正是同步模式的设计：部件只有一份数据源。只改单篇请先「脱离为常规区块」。</li><li><strong>问：浏览器意外崩溃，写的内容丢了吗？</strong> 答：大概率没有。自动保存每 60 秒提交一次，本地存储还留有最近输入；重开文章时编辑器会提示恢复本地版本。</li></ul><h2 id="本章总结" tabindex="-1">本章总结 <a class="header-anchor" href="#本章总结" aria-label="Permalink to &quot;本章总结&quot;">​</a></h2><ol><li>Gutenberg 自 5.0 取代 TinyMCE，把内容拆成区块；正文以 <code>wp:</code> HTML 注释 + JSON 配置保存，比短代码时代更结构化、更可移植。</li><li>界面五件套：顶栏、插入器（区块/模式/媒体 + 斜杠命令）、画布、区块工具栏、文档/区块双标签设置面板；复杂导航靠列表视图。</li><li>核心区块分文本、媒体、设计、主题、小工具五类；移动、变换、对齐、分组、复制、重复、锁定、复用是所有区块共通的操作语言。</li><li>模式是插入即独立的区块组合；可复用部件（同步模式）是「改一处全站变」的共享部件，可脱离为独立副本；行列 + 组 + 按钮可以搭出主流营销版面。</li><li>经典编辑器插件仅用于老站兼容；遇到无效区块依次尝试自动恢复、HTML 修正、修订恢复、重装插件；白屏与脏格式问题都有标准排查路径。</li></ol><h2 id="动手练习" tabindex="-1">动手练习 <a class="header-anchor" href="#动手练习" aria-label="Permalink to &quot;动手练习&quot;">​</a></h2><p><strong>练-07-01：用 8 种区块拼一篇产品介绍长文</strong> 新建文章「2026 年 WordPress 新手建站指南」，要求至少使用以下 8 种区块：标题、段落、列表、图片、封面、媒体和文本、行列、按钮（可再加表格/引用）。包含一个两栏布局和一个结尾行动号召区，排版完成后预览移动端堆叠效果，并用列表视图截图记录区块树。</p><p><strong>练-07-02：创建一个可复用 CTA 部件并验证同步</strong> 按 7.8 节创建一个「订阅周刊」可复用部件（标题 + 段落 + 按钮，设置背景色），插入到 3 篇不同文章；然后进入部件编辑，把按钮文案改成「免费订阅」，刷新三篇文章确认全部同步；最后任选一篇把该实例「脱离为常规区块」，再改原部件，观察脱离实例不再变化。</p><p><strong>练-07-03：观察插件卸载导致的区块失效</strong> 安装任一提供前台区块的官方插件（如某种 CTA/表单区块插件），插入区块并保存文章；停用插件后刷新文章，记录「无效区块」提示与处理选项；尝试「作为 HTML 编辑」找到该插件的 <code>wp:</code> 标记，最后重新启用插件恢复，并在笔记中写下这对内容资产长期维护的启示。</p><p><strong>练-07-04：在代码视图中读懂区块标记</strong> 打开练-07-01 的文章，切换到代码编辑器（<code>Ctrl/Cmd + Shift + Alt + M</code>），找出至少 5 处 <code>wp:</code> 注释，对照画布中的区块，在笔记中列出「区块名 → JSON 配置 → 实际 HTML」的对应关系；再对任意段落「编辑为 HTML」做一次小改动（如加一个 <code>&lt;strong&gt;</code>），切回可视化确认无误后更新。</p>',128)])])}const E=d(c,[["render",p]]);export{q as __pageData,E as default};
